import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, reproducible for a given seed.

    The same (n, seed) always yields the same list in the same order.
    Uses only a local random.Random(seed) instance: no global RNG state,
    no I/O, and no capabilities beyond pure computation.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**63), n)


def test_make_ids_length() -> None:
    assert len(make_ids(0, 1)) == 0
    assert len(make_ids(7, 1)) == 7


def test_make_ids_distinct() -> None:
    ids = make_ids(1000, 123)
    assert len(set(ids)) == 1000


def test_make_ids_deterministic_for_seed() -> None:
    assert make_ids(10, 42) == make_ids(10, 42)


def test_make_ids_varies_with_seed() -> None:
    assert make_ids(10, 1) != make_ids(10, 2)


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
